<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Setup extends CI_Controller {
 public function index(){ $this->load->database(); $count=(int)$this->db->count_all('users'); if($count>0){ return $this->page('Setup unavailable','An account already exists. For security, first-run setup is now disabled.',403); } $configured=(string)getenv('VP_SETUP_KEY'); $given=(string)($this->input->get_post('key',TRUE)?:''); if(strlen($configured)<16 || !hash_equals($configured,$given)){ return $this->page('First-run administrator','Enter the setup URL as https://yourdomain.com/setup?key=YOUR_VP_SETUP_KEY. The key must contain at least 16 characters.',403); } if($this->input->method(TRUE)==='POST'){ $d=$this->input->post(NULL,TRUE); if(!filter_var($d['email']??'',FILTER_VALIDATE_EMAIL)||strlen($d['password']??'')<12||empty($d['organization']))return $this->page('Invalid details','Use a valid email, organization, and password of at least 12 characters.',422,$given); $this->load->model('User_model','users'); try{$this->users->create_account(array('email'=>$d['email'],'password'=>$d['password'],'displayName'=>$d['display_name']?:'Administrator','organizationName'=>$d['organization'],'username'=>$d['username']?:NULL)); return $this->page('Administrator created','Setup is complete. Remove VP_SETUP_KEY from .env or replace it, then sign in on the homepage.',201);}catch(Throwable $e){log_message('error',$e->getMessage());return $this->page('Setup failed','The account could not be created. Check database import and credentials.',500,$given);} } return $this->page('Create first administrator','',200,$given); }
 private function page($title,$message,$status=200,$key=''){ http_response_code($status); $form=$key?'<form method="post"><input type="hidden" name="key" value="'.htmlspecialchars($key,ENT_QUOTES).'"><input name="email" type="email" placeholder="Administrator email" required><input name="username" placeholder="Username"><input name="display_name" placeholder="Display name" required><input name="organization" placeholder="Organization" required><input name="password" type="password" minlength="12" placeholder="Password (12+ characters)" required><button>Create administrator</button></form>':''; echo '<!doctype html><meta name="viewport" content="width=device-width"><title>'.htmlspecialchars($title).'</title><style>body{font:16px system-ui;max-width:560px;margin:8vh auto;padding:24px}input,button{width:100%;box-sizing:border-box;padding:12px;margin:6px 0}</style><h1>'.htmlspecialchars($title).'</h1><p>'.htmlspecialchars($message).'</p>'.$form; }
}
